16	ghost method isCelebrityP(n: int, i: int) returns (r : bool)
17	requires n >= 0 && 0 <= i < n;
18	ensures r <==> isCelebrity(n, i);
19	{
20	    var j := 0;
21	    r := true;
22	    while j < n
23	    decreases n - j;
24	    invariant 0 <= j <= n;
25	    invariant r ==> forall k :: 0 <= k < j && k != i ==> knows(k, i) && !knows(i, k);
26	    {
27	        if j != i {
28	            if !knows(j, i) || knows(i, j) {
29	                return false;
30	            }
31	        }
32	        j := j + 1;
33	    }
34	    return r;
35	} 
