37	ghost method findCelebrity(n : int) returns (r : int)
38	requires 2 <= n <= 100;
39	ensures 0 <= r < n ==> isCelebrity(n, r);
40	ensures r == -1 ==> forall i :: 0 <= i < n ==> !isCelebrity(n, i);
41	{
42	    var candidate := 0;
43	    var i := 1;
44	    while i < n 
45	    invariant 1 <= i <= n;
46	    invariant forall j :: 0 <= j < i && j != candidate ==> !isCelebrity(n, j);
47	    {
48	        if knows(candidate, i) {
49	            candidate := i;
50	        }
51	        i := i + 1;
52	    }
53	    //assert forall j :: 0 <= j < n && j != candidate ==> !isCelebrity(n, j);
54	    var isCelebrityC := isCelebrityP(n, candidate);
55	    if isCelebrityC {
56	        r := candidate;
57	    } else {
58	        r := -1;
59	    }
60	}

